CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,conversation TEXT NOT NULL DEFAULT '',subscription_hash TEXT);
CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),currency TEXT NOT NULL,duration INTEGER NOT NULL CHECK(duration>0 AND duration<=31536000),enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,plan_id TEXT NOT NULL,price INTEGER NOT NULL,currency TEXT NOT NULL,duration INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'awaiting_receipt' CHECK(state IN ('awaiting_receipt','pending_review','approved','rejected')),created_at INTEGER NOT NULL,request_key TEXT UNIQUE,decided_at INTEGER,decided_by TEXT,reason TEXT);
CREATE TABLE IF NOT EXISTS receipts(order_id TEXT PRIMARY KEY,file_id TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'document');
CREATE TABLE IF NOT EXISTS entitlements(user_id TEXT PRIMARY KEY,uuid TEXT NOT NULL,valid_until INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ledger(order_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,duration INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trials(user_id TEXT PRIMARY KEY,prepared_revision INTEGER,acked_revision INTEGER,started_at INTEGER);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS approved_order AFTER UPDATE OF state ON orders WHEN NEW.state='approved' AND OLD.state='pending_review' BEGIN  INSERT INTO ledger(order_id,user_id,duration,created_at) VALUES(NEW.id,NEW.user_id,NEW.duration,NEW.decided_at);  UPDATE entitlements SET valid_until=MAX(valid_until,NEW.decided_at)+NEW.duration,revoked=0 WHERE user_id=NEW.user_id;  INSERT INTO audit_events(actor_id,action,target_id,created_at) VALUES(NEW.decided_by,'approve_order',NEW.id,NEW.decided_at); INSERT OR IGNORE INTO outbox(id,chat_id,payload) VALUES('approved:'||NEW.id,NEW.user_id,json_object('text','پرداخت تأیید شد؛ آماده‌سازی اتصال. برای دریافت کانفیگ «اشتراک من» را بزن.'));  END;
 CREATE TRIGGER IF NOT EXISTS started_trial AFTER UPDATE OF started_at ON trials WHEN OLD.started_at IS NULL AND NEW.started_at IS NOT NULL BEGIN  UPDATE entitlements SET valid_until=MAX(valid_until,NEW.started_at+1800) WHERE user_id=NEW.user_id; END;
